          const dome = new THREE.Mesh(new THREE.SphereGeometry(rad, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.7), willowFoliageMat);
          dome.position.set(wx, 4.8, wz);
          hspGrp.add(dome);
