      // 1. Classic Double-Ended Toronto Island Ferry builder (Sam McBride / Ongiara / Thomas Rennie)
      function makeIslandFerry(name) {
        const fg = new THREE.Group();
        // Lower blue/black steel hull
        const hull = new THREE.Mesh(new THREE.BoxGeometry(11.5, 2.6, 38), hullBlue);
        hull.position.y = 0.6;
        fg.add(hull);
        // Tapered bows at both ends
        [-21.5, 21.5].forEach((bz, idx) => {
          const bow = new THREE.Mesh(new THREE.ConeGeometry(8.1, 6.5, 4), hullBlue);
          bow.rotation.x = idx === 0 ? -Math.PI / 2 : Math.PI / 2;
          bow.rotation.y = Math.PI / 4;
          bow.scale.set(1, 1, 0.32);
          bow.position.set(0, 0.6, bz);
          fg.add(bow);
        });
        // Orange/white main passenger deck
        const mainDeck = new THREE.Mesh(new THREE.BoxGeometry(10.8, 3.0, 32), hullWhite);
        mainDeck.position.y = 3.2;
        fg.add(mainDeck);
        const trimBand = new THREE.Mesh(new THREE.BoxGeometry(11.0, 0.65, 33), deckOrange);
        trimBand.position.y = 2.0;
        fg.add(trimBand);
        // Warm illuminated cabin window strip
        const winStrip = new THREE.Mesh(new THREE.BoxGeometry(10.95, 1.1, 28), cabinLit);
        winStrip.position.y = 3.4;
        fg.add(winStrip);
        // Upper open promenade deck & twin wheelhouses
        const upperDeck = new THREE.Mesh(new THREE.BoxGeometry(9.6, 2.2, 26), hullWhite);
        upperDeck.position.y = 5.6;
        fg.add(upperDeck);
        const wheelhouse = new THREE.Mesh(new THREE.BoxGeometry(5.2, 2.4, 6.5), hullWhite);
        wheelhouse.position.y = 7.8;
        fg.add(wheelhouse);
        const funnel = new THREE.Mesh(new THREE.CylinderGeometry(0.85, 0.95, 3.2, 12), deckOrange);
        funnel.position.y = 8.4;
        fg.add(funnel);
        const fSign = signMesh([name, 'TORONTO ISLAND FERRY'], 9.5, 1.1, { bg: '#1e3a8a', fg: '#fde047', borderColor: '#f97316', size: 58 });
        fSign.position.set(5.6, 5.6, 0);
        fSign.rotation.y = Math.PI / 2;
        fg.add(fSign);
        return fg;
      }
      // Moored Island Ferry at Jack Layton Ferry Terminal
